Fire.source:
// Fire -- particles born on a disc at the base, lifted by heat, buffeted by turbulence, cooling from white to red to smoke, then reborn.
//   data.x    = age, 0 at birth .. 1 at death
//   data.yzw  = velocity

// A swirling push that changes with position and time -- what makes the flames flicker
vec3 Turbulence(vec3 p, float time) {
    float x = sin(p.y * 3.1 + time * 2.3) + 0.5 * sin(p.z * 5.7 - time * 1.7);
    float y = 0.3 * sin(p.x * 4.3 + time * 1.9);
    float z = sin(p.y * 2.7 - time * 2.9) + 0.5 * sin(p.x * 6.1 + time * 1.3);

    return vec3(x, y, z);
}

// A random point on the base disc
vec3 SpawnPoint(uvec3 id, uint seed, float radius) {
    float pi = 3.14159265;
    float angle = Ir77Random(id, seed) * 2.0 * pi;
    float distance = sqrt(Ir77Random(id, seed + 1u)) * radius;  // sqrt spreads them evenly over the disc

    return vec3(cos(angle) * distance, 0.0, sin(angle) * distance);
}

// Colour by age: white-yellow -> orange -> red -> dark smoke
vec3 FireColour(float age) {
    vec3 white = vec3(1.0, 0.95, 0.7);
    vec3 orange = vec3(1.0, 0.5, 0.1);
    vec3 red = vec3(0.8, 0.1, 0.02);
    vec3 smoke = vec3(0.1, 0.1, 0.1);

    if (age < 0.15) return white + (orange - white) * (age / 0.15);
    if (age < 0.5) return orange + (red - orange) * ((age - 0.15) / 0.35);
    return red + (smoke - red) * ((age - 0.5) / 0.5);
}

Ir77FieldPoint Field(Ir77FieldIn f) {
    // sliders -> real values (0.5 = the middle of each range)
    float lift = 0.5 + (6.0 - 0.5) * f.params[0];          // how hard heat pushes up
    float turbulence = 0.0 + (4.0 - 0.0) * f.params[1];    // how much the flames flicker
    float lifetime = 0.5 + (3.0 - 0.5) * f.params[2];      // seconds a particle lives
    float base_radius = 0.1 + (1.5 - 0.1) * f.params[3];   // size of the burning disc
    float pinch = 0.0 + (3.0 - 0.0) * f.params[4];         // pull toward the centre -- the flame's tip
    float opacity = 0.01 + (0.2 - 0.01) * f.params[5];     // how bright each particle is
    float size = 0.01 + (0.08 - 0.01) * f.params[6];       // particle size at birth

    Ir77FieldPoint point = f.prev;

    float age = point.data.x;
    vec3 velocity = point.data.yzw;
    vec3 position = point.position;

    // this particle's own lifetime -- 60% .. 140% of the slider, so they don't all die together
    float my_lifetime = lifetime * (0.6 + 0.8 * Ir77Random(f.id, 4u));

    float dt = min(f.dt, 0.033);

    // first frame: born at the base, at a random point in its life, so the fire starts already burning
    if (f.first) {
        position = SpawnPoint(f.id, 1u, base_radius);
        velocity = vec3(0.0, 0.0, 0.0);
        age = Ir77Random(f.id, 5u);
    }

    // died: reborn at the base -- the seed changes with time, so it lands somewhere new each life
    if (age >= 1.0) {
        uint seed = uint(f.time * 997.0);
        position = SpawnPoint(f.id, seed, base_radius);
        velocity = vec3(0.0, 0.0, 0.0);
        age = 0.0;
    }

    // forces
    vec3 buoyancy = vec3(0.0, lift, 0.0);
    vec3 swirl = Turbulence(position, f.time) * turbulence;
    vec3 toward_centre = vec3(-position.x, 0.0, -position.z) * pinch;

    velocity = velocity + (buoyancy + swirl + toward_centre) * dt;

    // air drag -- velocity loses 2/3 every second, so particles don't speed up forever
    velocity = velocity * exp(-1.1 * dt);

    position = position + velocity * dt;
    age = age + dt / my_lifetime;

    // look: colour by age; fade in over the first 5% of life, fade out over the last 40%; grow as it cools
    float fade_in = age / 0.05;
    if (fade_in > 1.0) fade_in = 1.0;

    float fade_out = (1.0 - age) / 0.4;
    if (fade_out > 1.0) fade_out = 1.0;
    if (fade_out < 0.0) fade_out = 0.0;

    vec3 colour = FireColour(age);

    point.position = position;
    point.size = size * (1.0 + 2.0 * age);
    point.color = vec4(colour.x, colour.y, colour.z, opacity * fade_in * fade_out);
    point.data = vec4(age, velocity.x, velocity.y, velocity.z);

    return point;
}

Halvorsen.source:
// Halvorsen attractor -- every particle integrates from where it was last frame

// the velocity at point (x, y, z)
vec3 Halvorsen(float x, float y, float z, float a) {
    float dx = -a * x - 4.0 * y - 4.0 * z - y * y;
    float dy = -a * y - 4.0 * z - 4.0 * x - z * z;
    float dz = -a * z - 4.0 * x - 4.0 * y - x * x;

    return vec3(dx, dy, dz);
}

Ir77FieldPoint Field(Ir77FieldIn f) {
    // sliders -> real values (0.5 = the middle of each range)
    float a = 1.4 + (2.4 - 1.4) * f.params[0];          // damping: 1.89 is the classic shape
    float speed = 0.1 + (1.5 - 0.1) * f.params[1];      // how fast simulated time runs
    float scale = 0.15 + (0.45 - 0.15) * f.params[2];   // attractor units -> world units
    float opacity = 0.03 + (0.3 - 0.03) * f.params[3];  // particles add up where they overlap

    Ir77FieldPoint point = f.prev;  // where this particle was last frame

    // world -> attractor
    float x = point.position.x / scale;
    float y = point.position.y / scale;
    float z = point.position.z / scale;

    // does this particle need a new start?
    bool first_frame = f.first;
    bool broken = isnan(x) || isnan(y) || isnan(z);
    bool escaped = (x * x + y * y + z * z) > 1600.0;  // more than 40 units out

    if (first_frame || broken || escaped) {
        // a random point in the cube -2..2 on every axis
        x = Ir77Random(f.id, 1u) * 4.0 - 2.0;
        y = Ir77Random(f.id, 2u) * 4.0 - 2.0;
        z = Ir77Random(f.id, 3u) * 4.0 - 2.0;

        point.size = 0.008;
    }

    // this frame's time, split into 8 smaller steps -- Halvorsen moves fast, small steps keep it on the curve
    float frame_time = min(f.dt, 0.016);
    float step = frame_time * speed / 8.0;

    vec3 velocity = vec3(0.0, 0.0, 0.0);

    for (int i = 0; i < 8; i++) {
        velocity = Halvorsen(x, y, z, a);

        x = x + velocity.x * step;
        y = y + velocity.y * step;
        z = z + velocity.z * step;
    }

    // attractor -> world
    point.position = vec3(x * scale, y * scale, z * scale);

    // colour = distance from the centre: purple at the core, yellow out on the lobes
    float distance = sqrt(x * x + y * y + z * z);
    float t = distance / 12.0;
    if (t > 1.0) t = 1.0;

    vec3 core_colour = vec3(0.45, 0.1, 0.8);
    vec3 outer_colour = vec3(1.0, 0.85, 0.2);
    vec3 colour = core_colour + (outer_colour - core_colour) * t;

    point.color = vec4(colour.x, colour.y, colour.z, opacity);
    point.data = vec4(t, 0.0, 0.0, 0.0);  // data.x = distance 0..1, for the colormap shading

    return point;
}

Pickover.source:
// Pickover attractor -- a map, not a flow: every frame each particle jumps once to its next point.
// The cloud of all of them together is the attractor; the sliders reshape it live.

// one jump: the next point after (x, y, z)
vec3 Pickover(float x, float y, float z, float a, float b, float c, float d) {
    float next_x = sin(a * y) - z * cos(b * x);
    float next_y = z * sin(c * x) - cos(d * y);
    float next_z = sin(x);

    return vec3(next_x, next_y, next_z);
}

Ir77FieldPoint Field(Ir77FieldIn f) {
    // sliders -> real values. 0.5 = the classic shape (a 2.24, b 0.43, c -0.65, d -2.43); each slider moves its constant by +-1
    float a = 2.24 + (f.params[0] - 0.5) * 2.0;
    float b = 0.43 + (f.params[1] - 0.5) * 2.0;
    float c = -0.65 + (f.params[2] - 0.5) * 2.0;
    float d = -2.43 + (f.params[3] - 0.5) * 2.0;
    float scale = 0.5 + (2.5 - 0.5) * f.params[4];      // attractor units -> world units
    float opacity = 0.02 + (0.25 - 0.02) * f.params[5];  // particles add up where they overlap

    Ir77FieldPoint point = f.prev;  // where this particle was last frame

    // world -> attractor
    float x = point.position.x / scale;
    float y = point.position.y / scale;
    float z = point.position.z / scale;

    // first frame or broken maths -- a random start in the cube -1..1
    bool broken = isnan(x) || isnan(y) || isnan(z);

    if (f.first || broken) {
        x = Ir77Random(f.id, 1u) * 2.0 - 1.0;
        y = Ir77Random(f.id, 2u) * 2.0 - 1.0;
        z = Ir77Random(f.id, 3u) * 2.0 - 1.0;

        point.size = 0.006;
    }

    // one jump -- no dt, a map moves a whole step every frame
    vec3 next = Pickover(x, y, z, a, b, c, d);

    // attractor -> world
    point.position = vec3(next.x * scale, next.y * scale, next.z * scale);

    // colour by z (-1..1): teal at the bottom, magenta at the top
    float t = (next.z + 1.0) / 2.0;

    vec3 low_colour = vec3(0.1, 0.8, 0.8);
    vec3 high_colour = vec3(0.9, 0.2, 0.7);
    vec3 colour = low_colour + (high_colour - low_colour) * t;

    point.color = vec4(colour.x, colour.y, colour.z, opacity);
    point.data = vec4(t, 0.0, 0.0, 0.0);  // data.x = height 0..1, for the colormap shading

    return point;
}

Thomas.source:
// Thomas cyclically symmetric attractor -- every particle integrates from where it was last frame

// the velocity at point (x, y, z)
vec3 Thomas(float x, float y, float z, float b) {
    float dx = sin(y) - b * x;
    float dy = sin(z) - b * y;
    float dz = sin(x) - b * z;

    return vec3(dx, dy, dz);
}

Ir77FieldPoint Field(Ir77FieldIn f) {
    // sliders -> real values (0.5 = the middle of each range)
    float b = 0.10 + (0.30 - 0.10) * f.params[0];     // damping: ~0.208 is the classic lattice; lower = wilder
    float speed = 0.5 + (8.0 - 0.5) * f.params[1];    // how fast simulated time runs
    float scale = 0.4 + (1.2 - 0.4) * f.params[2];    // attractor units -> world units
    float opacity = 0.03 + (0.3 - 0.03) * f.params[3];  // particles add up where they overlap

    Ir77FieldPoint point = f.prev;  // where this particle was last frame

    // world -> attractor
    float x = point.position.x / scale;
    float y = point.position.y / scale;
    float z = point.position.z / scale;

    // does this particle need a new start?
    bool first_frame = f.first;
    bool broken = isnan(x) || isnan(y) || isnan(z);
    bool escaped = (x * x + y * y + z * z) > 400.0;  // more than 20 units out

    if (first_frame || broken || escaped) {
        // a random point in the cube -4..4 on every axis
        x = Ir77Random(f.id, 1u) * 8.0 - 4.0;
        y = Ir77Random(f.id, 2u) * 8.0 - 4.0;
        z = Ir77Random(f.id, 3u) * 8.0 - 4.0;

        point.size = 0.008;
    }

    // this frame's time, split into 4 smaller steps
    float frame_time = min(f.dt, 0.02);
    float step = frame_time * speed / 4.0;

    vec3 velocity = vec3(0.0, 0.0, 0.0);

    for (int i = 0; i < 4; i++) {
        velocity = Thomas(x, y, z, b);

        x = x + velocity.x * step;
        y = y + velocity.y * step;
        z = z + velocity.z * step;
    }

    // attractor -> world
    point.position = vec3(x * scale, y * scale, z * scale);

    // colour = the direction of travel: red along x, green along y, blue along z
    float length_of_velocity = length(velocity);
    vec3 direction = vec3(0.0, 0.0, 0.0);
    if (length_of_velocity > 0.0) direction = abs(velocity) / length_of_velocity;

    vec3 colour = vec3(0.15, 0.15, 0.15) + direction * 0.85;

    point.color = vec4(colour.x, colour.y, colour.z, opacity);
    point.data = vec4(length_of_velocity, 0.0, 0.0, 0.0);  // data.x = speed, for the colormap shading

    return point;
}

test001.source:
// Orientation test -- a ramp rising toward +y, a tall bump at (+2, +2), a short bump at (-2, -2).
// Top view must read like a graph: +x right, +y up.

Ir77FieldPoint Field(Ir77FieldIn f) {
    float x = f.coord.x;
    float y = f.coord.y;

    // gentle ramp: higher toward +y
    float ramp = 0.15 * y;

    // tall bump at (+2, +2)
    float tall_dx = x - 2.0;
    float tall_dy = y - 2.0;
    float tall = 1.5 * exp(-(tall_dx * tall_dx + tall_dy * tall_dy) / 0.5);

    // short bump at (-2, -2)
    float short_dx = x + 2.0;
    float short_dy = y + 2.0;
    float short_bump = 0.5 * exp(-(short_dx * short_dx + short_dy * short_dy) / 0.5);

    float height = ramp + tall + short_bump;

    Ir77FieldPoint point;
    point.position = vec3(x, height, -y);    // the convention: coord.y runs to -Z
    point.size = 0.0;
    point.color = vec4(0.7, 0.7, 0.7, 1.0);  // grey, for the lighting check
    point.data = vec4(y, 0.0, 0.0, 0.0);     // colour map by y: blue at -y, red at +y

    return point;
}
